{"content":"import csv

def verify():
    stops_ids = set()
    with open('outputs/t05_clean_stops.csv', mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            stops_ids.add(row['stop_id'])

    with open('outputs/t09_poi_nearest_stop.csv', mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            sid = row['nearest_stop_id']
            if sid not in stops_ids:
                print(f"Error: stop_id {sid} not found in t05_clean_stops.csv")

            dist = float(row['distance_m'])
            if dist < 0:
                print(f"Error: negative distance for {row['qid']}")

verify()
